import{_ as a,o as t,c as e,a4 as s}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"fnOS + k3s 第二发：containerd 生成 resolv.conf 权限 700 导致全站 Go 服务 DNS 崩溃","description":"","frontmatter":{"title":"fnOS + k3s 第二发：containerd 生成 resolv.conf 权限 700 导致全站 Go 服务 DNS 崩溃","date":"2026-09-01T00:00:00.000Z"},"headers":[],"relativePath":"posts/fnOS-k3s-ResolvConf权限700-Bug分析.md","filePath":"posts/fnOS-k3s-ResolvConf权限700-Bug分析.md"}'),n={name:"posts/fnOS-k3s-ResolvConf权限700-Bug分析.md"};function r(i,o,l,d,c,h){return t(),e("div",null,[...o[0]||(o[0]=[s(`<h1 id="fnos-k3s-第二发-containerd-生成-resolv-conf-权限-700-导致全站-go-服务-dns-崩溃" tabindex="-1">fnOS + k3s 第二发：containerd 生成 resolv.conf 权限 700 导致全站 Go 服务 DNS 崩溃 <a class="header-anchor" href="#fnos-k3s-第二发-containerd-生成-resolv-conf-权限-700-导致全站-go-服务-dns-崩溃" aria-label="Permalink to &quot;fnOS + k3s 第二发：containerd 生成 resolv.conf 权限 700 导致全站 Go 服务 DNS 崩溃&quot;">​</a></h1><blockquote><p>文档日期：2026-09-01 涉及设备：fnos（192.168.31.182，k3s v1.36.4+k3s1，containerd v1.7.29） 关联文档：<code>fnOS-vol1-权限000问题记录.md</code></p></blockquote><hr><h2 id="一、前情回顾" tabindex="-1">一、前情回顾 <a class="header-anchor" href="#一、前情回顾" aria-label="Permalink to &quot;一、前情回顾&quot;">​</a></h2><p>上一篇记录了 fnOS 已知内核 Bug——<code>/vol1</code> 目录权限被系统内核锁死为 <code>000</code>，导致 k3s 节点 NotReady、14 个服务全部 Pending。官方确认是内核层面的 umount 冲突问题，给出的&quot;修复方案&quot;是手动 chmod + 开机自检脚本。</p><p>我们照做了。问题暂时压下去了。</p><p><strong>但这只是 fnOS 内核 Bug 的第一层皮。</strong></p><hr><h2 id="二、新问题-go-服务全线-crashloopbackoff" tabindex="-1">二、新问题：Go 服务全线 CrashLoopBackOff <a class="header-anchor" href="#二、新问题-go-服务全线-crashloopbackoff" aria-label="Permalink to &quot;二、新问题：Go 服务全线 CrashLoopBackOff&quot;">​</a></h2><p>部署 fnos 节点后，所有 Go 后端服务（core、ai、bili、search、studio、work、msg-danmaku）启动即崩，日志清一色：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>failed to ping database: dial tcp: lookup postgres on [::1]:53: read udp [::1]:56319-&gt;[::1]:53: read: connection refused</span></span></code></pre></div><p>关键信息：<strong>DNS 解析走了 <code>[::1]:53</code>（IPv6 本地回环）而不是集群 kube-dns（<code>192.168.104.10</code>）。</strong></p><p>同期 laptop 节点上完全相同的镜像、完全相同的 YAML，一切正常。</p><hr><h2 id="三、排查过程-省流版" tabindex="-1">三、排查过程（省流版） <a class="header-anchor" href="#三、排查过程-省流版" aria-label="Permalink to &quot;三、排查过程（省流版）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查项</th><th>结果</th></tr></thead><tbody><tr><td>kube-dns 是否运行</td><td>正常，192.168.104.10 响应正常</td></tr><tr><td>Pod 的 resolv.conf 内容</td><td><code>nameserver 192.168.104.10</code>，内容正确</td></tr><tr><td>busybox nslookup 能否解析</td><td>能（因为 busybox 跑在 root，绕过了问题）</td></tr><tr><td>containerd sandbox resolv.conf 权限</td><td><strong><code>-rwx------</code>（700），只有 root 能读</strong></td></tr><tr><td>Pod 内 app 用户（uid=100）能否读 resolv.conf</td><td><strong>不能。<code>cat /etc/resolv.conf</code> → Permission denied</strong></td></tr><tr><td>Go 二进制（CGO_ENABLED=0）的 DNS 行为</td><td>读不了 resolv.conf → 回退到 <code>[::1]:53</code> → 崩</td></tr><tr><td>laptop 的 resolv.conf 权限</td><td><strong><code>-rw-r--r--</code>（644），所有人可读</strong></td></tr></tbody></table><p><strong>结论：containerd 在 fnos 上生成的 sandbox resolv.conf 权限是 700，非 root 用户无法读取。</strong></p><hr><h2 id="四、根因分析" tabindex="-1">四、根因分析 <a class="header-anchor" href="#四、根因分析" aria-label="Permalink to &quot;四、根因分析&quot;">​</a></h2><h3 id="_4-1-为什么-laptop-正常-fnos-就炸" tabindex="-1">4.1 为什么 laptop 正常，fnos 就炸？ <a class="header-anchor" href="#_4-1-为什么-laptop-正常-fnos-就炸" aria-label="Permalink to &quot;4.1 为什么 laptop 正常，fnos 就炸？&quot;">​</a></h3><p>containerd 创建 sandbox resolv.conf 时，文件权限取决于底层存储的行为。</p><ul><li><strong>laptop</strong>：标准 Linux 文件系统，umask 0022 正常生效，文件权限 644</li><li><strong>fnos</strong>：fnOS 定制内核 + ext4 + 特殊 ACL/prjquota → 文件创建时权限位被异常设置为 700</li></ul><p>这与 <code>/vol1</code> 权限锁死 000 是<strong>同一棵毒树上的不同果实</strong>——都是 fnOS 内核对文件/目录权限处理的 Bug。</p><h3 id="_4-2-为什么-busybox-能用-go-二进制不行" tabindex="-1">4.2 为什么 busybox 能用，Go 二进制不行？ <a class="header-anchor" href="#_4-2-为什么-busybox-能用-go-二进制不行" aria-label="Permalink to &quot;4.2 为什么 busybox 能用，Go 二进制不行？&quot;">​</a></h3><ul><li>busybox 默认以 <strong>root（uid=0）</strong> 运行 → 能读 700 权限的 resolv.conf</li><li>Go 服务 Dockerfile 里写了 <code>USER app</code>（uid=100）→ <strong>读不了</strong> 700 的 resolv.conf</li></ul><h3 id="_4-3-go-二进制为什么走-1-53" tabindex="-1">4.3 Go 二进制为什么走 [::1]:53？ <a class="header-anchor" href="#_4-3-go-二进制为什么走-1-53" aria-label="Permalink to &quot;4.3 Go 二进制为什么走 [::1]:53？&quot;">​</a></h3><p>Go 在 <code>CGO_ENABLED=0</code> 时使用内置 DNS 解析器：</p><ol><li>读 <code>/etc/resolv.conf</code> 获取 nameserver 列表</li><li>如果读不到（Permission denied）→ 回退到系统默认 → <code>[::1]:53</code></li><li><code>[::1]:53</code> 没有 DNS 服务 → 连接拒绝 → 所有域名解析失败</li></ol><p>这不是 Go 的 Bug，是 Go 的设计：<strong>读不了就回退，不报错给上层。</strong></p><h3 id="_4-4-为什么-admin-和-web-没崩" tabindex="-1">4.4 为什么 admin 和 web 没崩？ <a class="header-anchor" href="#_4-4-为什么-admin-和-web-没崩" aria-label="Permalink to &quot;4.4 为什么 admin 和 web 没崩？&quot;">​</a></h3><ul><li><strong>admin</strong>：前端 nginx 静态页面，不连数据库，启动不触发 DNS 查询</li><li><strong>web</strong>：同上，纯前端</li></ul><p>它们不是&quot;DNS 没问题&quot;，而是&quot;还没走到 DNS 那一步&quot;。</p><hr><h2 id="五、fnos-的锅有多大" tabindex="-1">五、fnOS 的锅有多大？ <a class="header-anchor" href="#五、fnos-的锅有多大" aria-label="Permalink to &quot;五、fnOS 的锅有多大？&quot;">​</a></h2><h3 id="这不是-偶发" tabindex="-1">这不是&quot;偶发&quot; <a class="header-anchor" href="#这不是-偶发" aria-label="Permalink to &quot;这不是&quot;偶发&quot;&quot;">​</a></h3><p>fnOS 官方把 <code>/vol1</code> 权限 000 定性为&quot;偶发&quot;，给个修复脚本就完事。现在 resolv.conf 权限 700 再次证明：<strong>fnOS 内核的权限处理存在系统性缺陷，不是修一个目录就能解决的。</strong></p><h3 id="这不是用户的问题" tabindex="-1">这不是用户的问题 <a class="header-anchor" href="#这不是用户的问题" aria-label="Permalink to &quot;这不是用户的问题&quot;">​</a></h3><ul><li>我们没有手动 umount 任何系统路径</li><li>我们没有修改任何系统权限设置</li><li>所有操作都是标准的 k3s + containerd 工作流</li></ul><p><strong>fnOS 内核在处理容器存储挂载时，对文件权限的管理有根本性缺陷。</strong></p><h3 id="这不是-k3s-的问题" tabindex="-1">这不是 k3s 的问题 <a class="header-anchor" href="#这不是-k3s-的问题" aria-label="Permalink to &quot;这不是 k3s 的问题&quot;">​</a></h3><ul><li>k3s 在 laptop（标准 Linux）上完全正常</li><li>同版本 k3s（v1.36.4+k3s1）</li><li>同版本 containerd（v1.7.29）</li></ul><p><strong>同样的软件栈，fnOS 内核就是跑不正常。</strong></p><h3 id="这不是第一次了" tabindex="-1">这不是第一次了 <a class="header-anchor" href="#这不是第一次了" aria-label="Permalink to &quot;这不是第一次了&quot;">​</a></h3><table tabindex="0"><thead><tr><th>事件</th><th>fnOS 内核 Bug</th><th>影响</th></tr></thead><tbody><tr><td>2026-08-30</td><td><code>/vol1</code> 权限锁死 000</td><td>k3s 节点 NotReady，14 服务全挂</td></tr><tr><td>2026-09-01</td><td>containerd resolv.conf 权限 700</td><td>Go 服务 DNS 崩溃，全站后端不可用</td></tr></tbody></table><p>两次，两种表现，同一个根源：<strong>fnOS 内核对文件/目录权限的处理有 Bug。</strong></p><hr><h2 id="六、fnos-官方的态度" tabindex="-1">六、fnOS 官方的态度 <a class="header-anchor" href="#六、fnos-官方的态度" aria-label="Permalink to &quot;六、fnOS 官方的态度&quot;">​</a></h2><ol><li><code>/vol1</code> 000 问题：确认是 Bug，给个修复脚本，说&quot;后续系统更新中会修复&quot;</li><li>resolv.conf 700 问题：<strong>目前未知，因为根本没人报过——普通用户不会去检查 containerd sandbox 的 resolv.conf 权限</strong></li></ol><p>fnOS 官方论坛上关于权限问题的帖子一堆又一堆，官方的标准回复模板：</p><blockquote><p>&quot;已知问题，后续更新修复，请耐心等待。&quot;</p></blockquote><p><strong>用户花钱买的是 NAS 系统，不是内核 Bug 实验田。</strong></p><hr><h2 id="七、我们的临时修复" tabindex="-1">七、我们的临时修复 <a class="header-anchor" href="#七、我们的临时修复" aria-label="Permalink to &quot;七、我们的临时修复&quot;">​</a></h2><h3 id="方案-修复-containerd-的-umask" tabindex="-1">方案：修复 containerd 的 umask <a class="header-anchor" href="#方案-修复-containerd-的-umask" aria-label="Permalink to &quot;方案：修复 containerd 的 umask&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># /etc/systemd/system/k3s.service.d/override.conf</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">[</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">Service</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">]</span></span>
<span class="line"><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;">UMask</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">=</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">0022</span></span></code></pre></div><p>让 k3s 进程及其子进程（containerd、shim）以 umask 0022 运行，新生成的 resolv.conf 就会是 644。</p><h3 id="验证步骤" tabindex="-1">验证步骤 <a class="header-anchor" href="#验证步骤" aria-label="Permalink to &quot;验证步骤&quot;">​</a></h3><ol><li>重启 k3s</li><li>检查新 sandbox 的 resolv.conf 权限</li><li>拉起一个 Go 服务，确认 DNS 正常</li></ol><hr><h2 id="八、给飞牛的一封信" tabindex="-1">八、给飞牛的一封信 <a class="header-anchor" href="#八、给飞牛的一封信" aria-label="Permalink to &quot;八、给飞牛的一封信&quot;">​</a></h2><p>飞牛技术团队：</p><p>你们好。</p><p>2026 年 8 月 30 日，你们的 fnOS 内核把 <code>/vol1</code> 权限锁成 000，我们写了修复脚本顶上去。</p><p>2026 年 9 月 1 日，同一个内核又把 containerd 生成的 resolv.conf 权限设成 700，导致所有 Go 服务 DNS 解析失败。</p><p>两次事故，两种表现，同一个根源：<strong>你们的内核在处理文件权限时有系统性 Bug。</strong></p><p>给一个修复脚本不叫&quot;解决&quot;，叫&quot;糊弄&quot;。用户重启一次能接受，重启两次还出问题，第三次谁还信？</p><p>我们是开发者，能查日志、能翻源码、能写 workaround。普通用户呢？他们只会看到&quot;服务连不上&quot;，然后找你们，然后得到一句&quot;已知问题，后续修复&quot;。</p><p><strong>请认真对待你们的内核权限管理 Bug。</strong></p><p>此致</p><p>一个被 fnOS 内核 Bug 折磨了两天的用户</p><hr><h2 id="九、后续建议" tabindex="-1">九、后续建议 <a class="header-anchor" href="#九、后续建议" aria-label="Permalink to &quot;九、后续建议&quot;">​</a></h2><ol><li>评估是否值得继续用 fnOS 跑 k3s（内核 Bug 随时可能再爆）</li><li>考虑迁移到标准 Linux 发行版（Ubuntu Server / Debian）跑 k3s</li><li>关注 fnOS 内核更新，确认权限 Bug 修复后才敢升级</li><li>所有 Go 服务的 Dockerfile 加一个兜底：entrypoint 里 <code>chmod 644 /etc/resolv.conf || true</code></li></ol>`,73)])])}const f=a(n,[["render",r]]);export{u as __pageData,f as default};
